def smallest_lexicographical_string(N, K, S):
    # Sort the string to get the smallest lexicographical order
    sorted_S = sorted(S)

    # Create the first subsequence with the first K characters
    first_subsequence = sorted_S[:K]

    # If the length of the first subsequence is less than K, we need to distribute the remaining characters
    if len(first_subsequence) < K:
        return ''.join(first_subsequence)
    else:
        # Check if we need to distribute the remaining characters
        remaining_chars = sorted_S[K:]
        # Find the first character in the first subsequence that is different from the (K-1)-th character
        first_different_index = K
        while first_different_index < N and sorted_S[first_different_index] == sorted_S[K - 1]:
            first_different_index += 1

        # If all characters from K to N are the same, we can just return the first subsequence
        if first_different_index == N:
            return ''.join(first_subsequence)
        else:
            # Otherwise, we need to distribute the remaining characters
            return ''.join(first_subsequence[:K - (first_different_index - K)]) + ''.join(sorted_S[first_different_index:])

